CREATE TABLE `account_sessions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `userId` int DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `loginType` varchar(30) NOT NULL DEFAULT 'google',
  `ipAddress` varchar(64) DEFAULT NULL,
  `macAddress` varchar(64) DEFAULT NULL,
  `deviceName` varchar(120) DEFAULT NULL,
  `userAgent` varchar(500) DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deviceId` varchar(120) DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_account_sessions_user` (`userId`),
  KEY `idx_account_sessions_email` (`email`),
  KEY `idx_account_sessions_type` (`loginType`),
  KEY `idx_account_sessions_device` (`deviceId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1770001;
