CREATE TABLE `quizzes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `subject` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `timeLimit` int DEFAULT '1800',
  `closingMessage` text DEFAULT NULL,
  `streakGoal` int DEFAULT '3',
  `feedback` json DEFAULT NULL,
  `questions` json NOT NULL,
  `isActive` tinyint(1) DEFAULT '1',
  `createdBy` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`createdBy`),
  UNIQUE KEY `quizzes_title` (`title`),
  CONSTRAINT `fk_1` FOREIGN KEY (`createdBy`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=270001;
/*!40014 SET FOREIGN_KEY_CHECKS=0*/;
/*!40101 SET NAMES binary*/;
CREATE TABLE `scores` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `quizId` int NOT NULL,
  `answers` json DEFAULT NULL,
  `score` int NOT NULL,
  `total` int NOT NULL,
  `percentage` float DEFAULT '0',
  `timeTaken` int DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `deletedAt` datetime DEFAULT NULL,
  `isOfficial` tinyint(1) DEFAULT '1',
  `attemptNumber` int DEFAULT '1',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `fk_1` (`userId`),
  KEY `fk_2` (`quizId`),
  KEY `scores_quiz_id_percentage` (`quizId`,`percentage`),
  KEY `scores_user_id` (`userId`),
  KEY `idx_scores_user_deleted` (`userId`,`deletedAt`),
  KEY `scores_user_id_quiz_id` (`userId`,`quizId`),
  CONSTRAINT `fk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE,
  CONSTRAINT `fk_2` FOREIGN KEY (`quizId`) REFERENCES `quizzes` (`id`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=720001;
/*!40014 SET FOREIGN_KEY_CHECKS=0*/;
/*!40101 SET NAMES binary*/;
CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `googleId` varchar(255) DEFAULT NULL,
  `avatar` varchar(500) DEFAULT '',
  `fname` varchar(50) DEFAULT '',
  `lname` varchar(50) DEFAULT '',
  `isProfileComplete` tinyint(1) DEFAULT '0',
  `role` enum('student','admin') DEFAULT 'student',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `tokenVersion` int NOT NULL DEFAULT '0' COMMENT 'Incremented on logout/revoke to invalidate all existing tokens',
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `googleId` (`googleId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1020001;
