INSERT INTO `quizzes` VALUES
(1,'الصرف - دعصام عامرية - الأربع الأوَل','الصرف','هذا امتحان على اول اربع محاضرات للدكتور عصام عامرية في علم الصرف',900,'نفع الله بك يا سيبويه 🌹',3,'{}','[{\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"اسْتَحَبَّ\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"حَبَّذا\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يُحِبُّ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أَحْبَبْتُ\"}], \"hint\": \"\", \"id\": \"652e7254-a33d-4727-9df8-695acfd250f4\", \"question\": \"أيُّ الأفعال الآتية يُعَدُّ جامدًا لا يتصرّف، مع دلالته على معنى المدح؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"فَكَّ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تَفَكَّكَ\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"ما انفكَّ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"انفكَّ\"}], \"hint\": \"\", \"id\": \"7c6124e1-f486-4830-8ec7-c3ae682fc252\", \"question\": \"أيُّ الأفعال الآتية ناقصُ التصرّف يكتفي بالماضي والمضارع دون الأمر؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"آتى\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"هاتِ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يؤتي\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ائتِ\"}], \"hint\": \"\", \"id\": \"8cd6d169-a512-420f-b7fe-3c26dd559daf\", \"question\": \"الفعل الذي يلازم صيغة الأمر ولا يُستعمل منه ماضٍ ولا مضارع هو:\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"يَفْهَمُ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يُفْهَمُ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يُفْهِمُ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يِفْهَمُ\"}], \"hint\": \"\", \"id\": \"629cda5f-f849-47b1-a313-c54c07e87f1b\", \"question\": \"عند تحويل الفعل الثلاثي (فَهِمَ) إلى المضارع يكون ضبط حرف المضارعة:\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"مضمومًا\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"مفتوحًا\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"مكسورًا\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ساكنًا\"}], \"hint\": \"\", \"id\": \"4a7263d5-f6e2-4135-9ce9-36e32edaba79\", \"question\": \"عند إسناد الفعل الرباعي (دحرج) إلى المضارع يكون حرف المضارعة:\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"استخرجْ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"اُستَخرِجْ\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"استَخرِجْ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يُستخرجْ\"}], \"hint\": \"\", \"id\": \"31ff99d2-018d-40b3-8bb6-1e0a1e06b445\", \"question\": \"صياغة الأمر من الفعل (يستخرج) هي:\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"بِعْ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"بَيْعْ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"اِبِعْ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"يُبَعْ\"}], \"hint\": \"\", \"id\": \"c11ac295-ae54-40e6-9252-aa983e3b7e31\", \"question\": \"صياغة الأمر من (يبيع) على القياس الصحيح هي:\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"ضُرِبَ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ضَرِبَ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ضُرَبَ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ضَرَبَ\"}], \"hint\": \"\", \"id\": \"341c475a-ea3a-4772-9e83-c947930657b9\", \"question\": \"عند بناء الفعل الثلاثي الصحيح (ضرب) للمجهول في الماضي يكون:\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"قُيِلَ\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"قِيلَ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"قَالَ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"قُوِلَ\"}], \"hint\": \"\", \"id\": \"f9cbfbd2-0f1a-4a77-8b14-16d652a3e4f