(180001,'علم البيان - دكمال - الأربع الأول','علم البيان','اختبار على أول أربعة محاضرات للدكتور كمال عبد العزيز في فرع علم البيان',1200,'نفع الله بك ووفقك',3,'{}','[{\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"الغرابة واستعمال الألفاظ المهجورة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الابتذال وشيوع اللفظ على ألسنة العامة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"مخالفة القياس الصرفي المعتمد\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تنافر الحروف بنوعيه الشديد والخفيف\"}], \"hint\": \"يرتبط بالألفاظ الحوشية غير المألوفة\", \"id\": \"dfc9c0df-50db-4269-866a-f12b2932d6d7\", \"question\": \"استناداً إلى معايير فصاحة الكلمة المفردة، أي العيوب الآتية يجبر المتلقي على الاستعانة بالمعاجم المتخصصة لفك شفرة النص؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأن الأولى كلمة حوشية مهجورة بينما الثانية مبتذلة سوقية\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"لأن الأولى تسبب ثقلاً يعرقل اللسان تماماً بينما الثانية تسبب ثقلاً خفيفاً لا يمنع النطق\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأن الأولى تتكون من حروف متباعدة المخارج بينما الثانية متقاربة المخارج\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأن الأولى تخالف القياس الصرفي بينما الثانية تخالف العرف الدلالي\"}], \"hint\": \"يعتمد على درجة إعاقة النطق\", \"id\": \"f8201c17-d1b6-426b-be69-11264c23f825\", \"question\": \"ما المبرر الدقيق لاعتبار كلمة \\\"الظَّش\\\" مصابة بعيب التنافر الشديد مقارنة بكلمة \\\"نُقَاخ\\\"؟\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"ثقل نطق الكلمة يماثل تماماً البطء الحركي للمتكاسلين وتثاقلهم عن المعركة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"طول الكلمة يعكس المعاناة الشديدة في محاولة الإقناع المستميتة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"التنافر الصوتي رسم صورة سمعية دقيقة لالتواء المعاني في نفوس المنافقين\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تكرار الحروف يصور مشهد تدافعهم وسقوطهم في وحل الهزيمة\"}], \"hint\": \"علاقة جرس الكلمة بالمعنى الحركي\", \"id\": \"036012db-1112-4f3b-8a7b-e50ab45363d6\", \"question\": \"في قوله تعالى: {لَيُبَطِّئَنَّ}، ما هو \\\"السر البلاغي\\\" الذي جعل اللفظة في قمة الفصاحة رغم ثقل حروفها المجردة؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ليعكس حالة التردد والقلق الداخلي لدى قوم نوح قبل اتخاذ قرار الرفض\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"ليصور المعاناة الشديدة والمحاولة المستميتة من النبي لإقناع قومه وكأنه يدس الفكرة بعقولهم\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ليمثل البطء الحركي والتثاقل الذي اتسم به الكافرون عند سماع الموعظة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ليبرز التنافر الصوتي الذي يعكس نفور القوم من دعوة التوحيد\"}], \"hint\": \"يصور حالة من المشقة الدعوية\", \"id\": \"1745ee08-155b-48aa-aa6e-d709c7678379\", \"question\": \"كيف وظّف القرآن الكريم دلالة \\\"الطول والثقل\\\" في لفظة {أَنُلْزِمُكُمُوهَا} لخدمة السياق البلاغي في قصة نوح عليه السلام؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"مطابقة التكرار اللفظي لطول مدة العذاب في الآخرة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الإشارة إلى الغرابة والوحشية في نوع العذاب المعد للكافرين\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"تصوير مشهد تدافع أهل النار وسقوطهم المتكرر على وجوههم\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"رسم صورة سمعية دقيقة لتنافر أفكار أهل النار وتداخلها\"}], \"hint\": \"تجسيد حركي لمشهد العذاب\", \"id\": \"4200d73c-4cf6-4c15-8f8b-56128121caa5\", \"question\": \"ما العلة البلاغية وراء جمالية التكرار الصوتي (الكبكبة) في الفعل القرآني {فَكُبْكِبُوا}؟\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"لأن التنافر رسم صورة سمعية دقيقة لتنافر وتداخل الشعر (الضفائر) الملتوي والمرفوع\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأنها وافقت القياس الصرفي الدقيق لوزن مستفعلات متجاهلة ثقل النطق\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأنها جاءت في سياق حماسي يتطلب ألفاظاً قوية ومجلجلة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لأنها ابتعدت عن الابتذال الذي تمجه الآذان في وصف الجمال الأنثوي\"}], \"hint\": \"التنافر الصوتي يخدم الصورة البصرية\", \"id\": \"da02b898-9dd4-4181-a871-a09da7357f49\", \"question\": \"لماذا ارتقت كلمة \\\"مُسْتَشْزِرَاتٍ\\\" في قصيدة امرئ القيس لتصبح قمة في البلاغة رغم ما فيها من تنافر حروفي؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"استخدام لفظة أعجمية (بوق) لا تخضع لقواعد الاشتقاق العربية\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الابتذال اللفظي عبر استدعاء آلات موسيقية تهبط بمستوى المديح\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"التنافر الشديد بين مخرجي القاف والتاء في بنية الكلمة المفرده\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"الجمع باستخدام المؤنث السالم بدلاً من جمع التكسير القياسي (أبواق)\"}], \"hint\": \"خطأ في اختيار صيغة الجمع\", \"id\": \"25d0460a-b990-4ecd-a202-4972ddefb2b2\", \"question\": \"في قول المتنبي: \\\"فَفِي النَّاسِ بُوقَاتٌ لَهَا وَطُبُولُ\\\"، ما الوجه الدقيق للخلل البلاغي الذي أوقع الشاعر في مخالفة العرف اللغوي؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الفصاحة تتحقق بمجرد مطابقة الكلمة لقواعد النحو والصرف دون النظر لجرسها\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"الفصاحة تعتمد على النظم والسياق وملائمة الكلمة لما يجاورها وليس بمعزل عن التركيب\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الفصاحة ترتبط بالغرابة المعجمية التي تثير انتباه المتلقي\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الفصاحة تعتمد كلياً على خلو اللفظة من حروف الاستعلاء المتقاربة\"}], \"hint\": \"الفصاحة ليست في المفردة المعزولة\", \"id\": \"981f0a6c-a483-490d-8d14-a7e7deac2ac8\", \"question\": \"أي القواعد الآتية استنبطها البلاغيون من جمالية ألفاظ مثل (ليبطئن، مستشزرات) رغم ثقلها المجرد؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"خلو الجملة تماماً من أي كلمات تتضمن حروفاً من نفس المخرج الصوتي\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"الذوق السليم الذي يمج الثقل ويشترط أن يتميز الكلام بموسيقى خفيفة عذبة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"القدرة على قراءة البيت الشعري كاملاً في نفس واحد دون توقف\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تطبيق قواعد النحو الصارمة في بناء الجملة الفعلية\"}], \"hint\": \"مقياس حسي وجمالي\", \"id\": \"a979ff34-756c-404a-8664-133c378a2d5d\", \"question\": \"ما هو المعيار الدقيق الذي اعتمده \\\"الجاحظ\\\" للحكم على خلو العبارة من عيب \\\"تنافر الكلمات مجتمعة\\\"؟\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"وقبرُ حَرْبٍ بمكانٍ قَفْرٍ .. وليسَ قُرْبَ قَبْرِ حَرْبٍ قَبْرُ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"وشعر كبَعْر الكبش فُرِّقَ بينه\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"فَإِنْ يَكُ بَعْضُ النَّاسِ سَيْفاً لِدَوْلَةٍ\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أَدَبَّجَ زَوْجُ هَزَّ رَفَّارٍ .. هَرِفٍ يَبُدُّ الناجياتِ الصَّوافِنَا\"}], \"hint\": \"بيت يكرر القاف والباء والراء\", \"id\": \"5a4f3df1-b70d-47d3-a4dd-5a359e4718fc\", \"question\": \"أي الشواهد الآتية يمثل عيب \\\"تنافر الكلمات مجتمعة\\\" لدرجة يصعب معها إنشاده متتالياً دون تعتعة؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الشين واللام\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"القاف والباء\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"الزاي والجيم\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"الفاء والراء\"}], \"hint\": \"تكرار يرهق عضلة اللسان\", \"id\": \"ffb42fba-204b-40c9-aecd-8298dddfd15d\", \"question\": \"ما الحروف التي تسببت في عيب \\\"التنافر الشديد\\\" في قول الشاعر: \\\"أَدَبَّجَ زَوْجُ هَزَّ رَفَّارٍ\\\"؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"tex