\"علم النقد\"}], \"hint\": \"علم الزينة اللفظية والمعنوية\", \"id\": \"1dce590f-bfca-4ee2-bc79-ace747c1acd0\", \"question\": \"أي العلوم البلاغية يهتم بـ \\\"التورية\\\" كوجه من وجوه تحسين الكلام؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن يعتمد حصرياً على الكلمات ثلاثية الأحرف\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن يقتصر على المعاني الحقيقية دون المجازية\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن يخلو من أي تقديم أو تأخير\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"أن يتميز بموسيقى خفيفة عذبة يقبلها الذوق السليم\"}], \"hint\": \"يتعلق بالانسيابية السمعية\", \"id\": \"0d3f6b65-09fd-459d-ae9d-8bd9053aebb5\", \"question\": \"في مقولة الجاحظ حول مقياس تنافر الكلمات مجتمعة، ما هو الشرط الأساسي الذي يجب أن يتوفر في الكلام؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"نعم، يقتصر عليهما فقط لضمان سلامة التركيب\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"لا، بل يشمل الجانب النحوي والصرفي والدلالي\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"نعم، لأن الجانب الدلالي يخص علم البديع حصراً\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"لا، بل يشمل الجانب الصوتي والعروضي فقط\"}], \"hint\": \"هناك جانب ثالث يرتبط بالمعنى\", \"id\": \"5a7537ec-9e6b-4f18-b6a0-8e2c9a973c9b\", \"question\": \"في تعريف \\\"مخالفة العرف اللغوي\\\"، هل يقتصر الخروج عن الثابت على النحو والصرف فقط؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تدافع الكفار في النار\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"صعوبة إقناع الأقوام برسالات الأنبياء\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"تنافر وتداخل الشعر (الضفائر) الملتوي المرفوع\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"ثقل سير الإبل في الصحراء\"}], \"hint\": \"حالة تشابك معقدة\", \"id\": \"96b6f05d-6d9d-4625-8000-44cd2b46d051\", \"question\": \"ما هو المعنى الذي ترسمه لفظة \\\"مستشزرات\\\" من خلال تنافر حروفها؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"استعمال لفظ سوقي متبذل\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"استعمال كلمة حوشية غير مألوفة\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تكرار الحروف المتقاربة لدرجة تعيق النطق\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"جمع كلمة على غير قياسها الصرفي\"}], \"hint\": \"وصف يتطلب معجماً لمعرفة القصد منه\", \"id\": \"85a3cafe-2d8f-49b2-8618-11345d548a18\", \"question\": \"أي مما يلي يعتبر مثالاً على عيب \\\"الغرابة\\\" في فصاحة الكلمة؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن القرآن يتجاوز قواعد البلاغة البشرية بالكامل\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن العرف اللغوي لا قيمة له في تقييم النصوص الدينية\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"أن التنافر الشديد هو ميزة قرآنية مطلقة في كل المواضع\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"أن الفصاحة تعتمد على النظم والسياق وليس على اللفظة مفردة بمعزل عن التركيب\"}], \"hint\": \"قاعدة أساسية في البلاغة\", \"id\": \"5c2cfd57-5309-45bd-b1b5-97dc42a6257c\", \"question\": \"وفقاً للمحاضرة الثالثة، ماذا نستنتج من إعجاز القرآن في استخدام كلمات ثقيلة الحروف مثل (أتلزمكموها)؟\"}, {\"answerOptions\": [{\"isCorrect\": true, \"rationale\": \"\", \"text\": \"علم المعاني\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"علم البديع\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"علم البيان\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"علم المنطق\"}], \"hint\": \"علم يطابق مقتضى الحال\", \"id\": \"bf7fae42-7564-4e6d-9a09-41ae8d0b9611\", \"question\": \"إذا استخدم الشاعر كلمة \\\"القصر\\\" بدلاً من \\\"التقديم والتأخير\\\" لإفادة التخصيص، فهو يطبق قواعد أي علم؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"بسبب ضعف التأليف النحوي في الجملة الاسمية\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"بسبب الابتذال في تكرار ذكر القبور\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"بسبب اجتماع الكلمات الذي يولد ثقلاً وصعوبة في النطق\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"بسبب استخدام المجاز في غير موضعه الصحيح\"}], \"hint\": \"العيب في المجموع لا في المفرد\", \"id\": \"407696eb-a42a-4ea4-891d-22d07b765c46\", \"question\": \"في الشاهد: \\\"وليس قرب قبر حرب قبر\\\"، لماذا فُقدت الفصاحة رغم أن كل كلمة فصيحة بمفردها؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"هو الاستعمال الأصلي للفظ كما جاء في القاموس\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"هو استعمال اللفظ في غير ما وضع له أصلاً (مفهوم من مقابلة الحقيقة)\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"هو تحسين الكلام بعد التأكد من سلامته النحوية\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"هو الجانب التطبيقي والموهبة في إنشاء الكلام\"}], \"hint\": \"يقابل الحقيقة اللغوية\", \"id\": \"02dc7633-5ec2-4f73-b3c9-b5bd12962781\", \"question\": \"ما الوصف الدقيق لـ \\\"المجاز\\\" استناداً إلى تمهيد علم البيان المذكور؟\"}]',1,90001,'2026-03-10 20:01:34','2026-03-13 18:14:37',NULL),
(210001,'اختبار تجريبي','الصرف','',1800,'شكراً لمشاركتك في الاختبار!',3,'{}','[{\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تفاعل\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"انفعل\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"افعل\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"افتعل\"}], \"hint\": \"\", \"id\": \"2fc8965f-80c5-48e4-8340-511a5de948d8\", \"question\": \"ما هو الوزن الصرفي للفعل (انطلق)؟\"}, {\"answerOptions\": [{\"isCorrect\": false, \"rationale\": \"\", \"text\": \"انفعال\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"افتعال\"}, {\"isCorrect\": false, \"rationale\": \"\", \"text\": \"تفعيل\"}, {\"isCorrect\": true, \"rationale\": \"\", \"text\": \"استفعال\"}], \"hint\": \"\", \"id\": \"9eba3408-cbb6-44d9-88af-6ee8e3ace724\", \"question\": \"ما هو الوزن الصرفي لكلمة (استغفار)؟\"}]',1,1,'2026-03-13 06:48:26','2026-03-13 06:48:26','2026-03-13 06:49:50');
